# RustDesk host deployment kit launcher. Reads kit.json next to it (generated by the
# host-installer workflow from repository secrets, shipped only inside the encrypted kit).
$here = Split-Path -Parent $MyInvocation.MyCommand.Path
$cfgPath = Join-Path $here "kit.json"
$cfg = if (Test-Path $cfgPath) { Get-Content $cfgPath -Raw | ConvertFrom-Json } else { $null }
$msi = Get-ChildItem $here -Filter *.msi | Select-Object -First 1
if (-not $msi) { throw "No .msi found next to this script." }

$hostPwd = Read-Host "Permanent RustDesk password for this device (Enter = none)" -AsSecureString
$plain = [Runtime.InteropServices.Marshal]::PtrToStringAuto([Runtime.InteropServices.Marshal]::SecureStringToBSTR($hostPwd))
$tag = Read-Host "Tag for this device, e.g. customer or site (Enter = none)"

$params = @{ Msi = $msi.FullName; Password = $plain }
if ($cfg -and $cfg.ApiServer -and $cfg.AbUser -and $cfg.AbPassword) {
    $params.ApiServer = $cfg.ApiServer
    $params.AbUser = $cfg.AbUser
    $params.AbPassword = $cfg.AbPassword
    if ($cfg.AbCollection) { $params.AbCollection = $cfg.AbCollection }
}
if ($tag) { $params.Tags = @($tag) }

& (Join-Path $here "deploy-host.ps1") @params
Read-Host "Done. Write down the ID above, then press Enter"
